#include <stddef.h>
#include <stdint.h>
#include <string.h>

enum { IE_SESSION_ID = 0x12, IE_SNSSAI = 0x22 };

typedef struct {
    uint8_t session_id;
    int has_snssai;
    uint8_t snssai[4];
} SessionContext;

static int put_ie(uint8_t *buf, size_t cap, size_t *off,
                  uint8_t id, const uint8_t *value, uint8_t n) {
    if (*off > cap || cap - *off < (size_t)n + 2u) return -1;
    buf[*off] = id;
    buf[*off + 1] = n;
    memcpy(buf + *off + 2, value, n);
    *off += (size_t)n + 2u;
    return 0;
}

int encode_session_context(const SessionContext *ctx, uint8_t *buf,
                           size_t cap, size_t *written) {
    if (ctx == NULL || buf == NULL || written == NULL) return -1;
    if (ctx->session_id == 0 || ctx->session_id > 15) return -2;

    size_t off = 0;
    uint8_t sid = ctx->session_id;
    if (put_ie(buf, cap, &off, IE_SESSION_ID, &sid, 1) != 0) return -3;
    if (ctx->has_snssai &&
        put_ie(buf, cap, &off, IE_SNSSAI, ctx->snssai, 4) != 0) return -3;

    *written = off;
    return 0;
}

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define MAX_FLOWS 16

typedef struct {
    uint8_t qfi;
    uint8_t five_qi;
    bool reflective;
} Flow;

typedef struct {
    size_t count;
    Flow items[MAX_FLOWS];
} FlowList;

int decode_flow_list(const uint8_t *value, size_t len, FlowList *out) {
    if (value == NULL || out == NULL) return -1;
    if (len < 1) return -2;

    uint8_t count = value[0];
    if (count > MAX_FLOWS || len != 1u + (size_t)count * 3u) return -2;

    FlowList tmp = {0};
    size_t off = 1;
    for (size_t i = 0; i < count; ++i) {
        uint8_t qfi = value[off];
        uint8_t five_qi = value[off + 1];
        uint8_t flags = value[off + 2];
        if (qfi == 0 || qfi > 63 || five_qi == 0 || (flags & 0xfeu) != 0)
            return -3;
        for (size_t j = 0; j < i; ++j) {
            if (tmp.items[j].qfi == qfi) return -3;
        }
        tmp.items[i].qfi = qfi;
        tmp.items[i].five_qi = five_qi;
        tmp.items[i].reflective = (flags & 0x01u) != 0;
        off += 3;
    }

    tmp.count = count;
    *out = tmp;
    return 0;
}

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

enum { IE_SESSION_ID = 0x12, IE_CAUSE = 0x58 };

typedef struct {
    uint8_t session_id;
    uint8_t cause;
    bool has_cause;
} ReleaseInfo;

int decode_release(const uint8_t *buf, size_t len, ReleaseInfo *out) {
    if (buf == NULL || out == NULL) return -1;

    ReleaseInfo tmp = {0};
    bool has_session = false;
    size_t off = 0;
    while (off < len) {
        if (len - off < 2) return -2;
        uint8_t id = buf[off++];
        uint8_t n = buf[off++];
        if ((size_t)n > len - off) return -2;
        const uint8_t *v = buf + off;

        if (id == IE_SESSION_ID) {
            if (n != 1 || has_session) return -3;
            tmp.session_id = v[0];
            has_session = true;
        } else if (id == IE_CAUSE) {
            if (n != 1 || tmp.has_cause) return -3;
            tmp.cause = v[0];
            tmp.has_cause = true;
        }
        off += n;
    }

    if (!has_session || tmp.session_id == 0) return -4;
    *out = tmp;
    return 0;
}
